class Solution {
public:
    int longestSubsequence(std::vector<int>& arr, int difference) {
        std::unordered_map<int, int> dp;
        int ans = 0;
        for (int x : arr) {
            dp[x] = dp[x - difference] + 1;
            ans = std::max(ans, dp[x]);
        }
        return ans;
    }
};

class Solution {
    public int longestSubsequence(int[] arr, int difference) {
        java.util.Map<Integer, Integer> dp = new java.util.HashMap<>();
        int ans = 0;
        for (int x : arr) {
            int len = dp.getOrDefault(x - difference, 0) + 1;
            dp.put(x, len);
            ans = Math.max(ans, len);
        }
        return ans;
    }
}

var longestSubsequence = function(arr, difference) {
    const dp = new Map();
    let ans = 0;
    for (const x of arr) {
        const len = (dp.get(x - difference) || 0) + 1;
        dp.set(x, len);
        if (len > ans) ans = len;
    }
    return ans;
};
